        await finalizeSecretaryWriteTask(pendingCreationWrite.taskId, 'succeeded', `创作已经原子写入 Obsidian；本地界面状态同步失败：${error}`);
        showToast(`创作已写入 Obsidian，但本地状态同步失败：${error}`, 'error');
