function isTextAttachment(file) {
  const descriptor = attachmentDurableDescriptor(file);
  const name = String(file?.name || descriptor?.fileName || '').toLowerCase();
  const type = String(file?.type || file?.mimeType || descriptor?.mimeType || '').toLowerCase();
  return type.startsWith('text/') || /\.(?:txt|md|markdown|csv|json|xml|html|yaml|yml|log|js|ts|jsx|tsx|rs|py|css)$/u.test(name);
}

function imageAnalysisText(attachment) {
  const analysis = attachment?.imageAnalysis;
  if (!analysis?.summary) return '';
  return renderPrompt('assistant.image-analysis-record', {
    IMAGE_NAME: attachment.name,
    SUMMARY: analysis.summary,
    VISIBLE_TEXT: analysis.text ? renderPrompt('assistant.image-analysis-visible-text', { VISIBLE_TEXT: analysis.text }) : '',
    KEY_POINTS: analysis.keyPoints?.length ? renderPrompt('assistant.image-analysis-key-points', { KEY_POINTS: analysis.keyPoints.join('；') }) : '',
    TAGS: analysis.tags?.length ? renderPrompt('assistant.image-analysis-tags', { TAGS: analysis.tags.join('、') }) : '',
    MODEL_ID: analysis.modelId || '未记录',
    ANALYZED_AT: analysis.analyzedAt || '未记录',
  });
}

async function canvasBlob(canvas, type, quality) {
  return new Promise((resolve, reject) => canvas.toBlob((blob) => {
    if (blob) resolve(blob);
    else reject(new Error('无法生成模型可读取的图片数据'));
  }, type, quality));
}

async function imageFileToAnalysisDataUrl(file, requestedMaxEdge = 2048) {
  const directTypes = new Set(['image/jpeg', 'image/png', 'image/webp', 'image/gif']);
  if (file.size <= 3 * 1024 * 1024 && directTypes.has(file.type)) {
    const bytes = new Uint8Array(await file.arrayBuffer());
    return `data:${file.type};base64,${bytesToBase64(bytes)}`;
  }
  const bitmap = await createImageBitmap(file);
  try {
    let maxEdge = requestedMaxEdge;
    for (let attempt = 0; attempt < 5; attempt += 1) {
      const scale = Math.min(1, maxEdge / Math.max(bitmap.width, bitmap.height));
      const canvas = document.createElement('canvas');
      canvas.width = Math.max(1, Math.round(bitmap.width * scale));
      canvas.height = Math.max(1, Math.round(bitmap.height * scale));
      const context = canvas.getContext('2d', { alpha: false });
      context.fillStyle = '#ffffff';
      context.fillRect(0, 0, canvas.width, canvas.height);
      context.drawImage(bitmap, 0, 0, canvas.width, canvas.height);
      const blob = await canvasBlob(canvas, 'image/jpeg', Math.max(0.66, 0.9 - attempt * 0.06));
      if (blob.size <= 3.5 * 1024 * 1024 || attempt === 4) {
        const bytes = new Uint8Array(await blob.arrayBuffer());
        return `data:image/jpeg;base64,${bytesToBase64(bytes)}`;
      }
      maxEdge = Math.max(768, Math.round(maxEdge * 0.75));
    }
  } finally {
    bitmap.close();
  }
  throw new Error(`图片“${file.name}”无法生成模型输入`);
}

function assistantImageAnalysisRecord(analysis, modelId, mode) {
  const values = captureAnalysisValues(analysis);
  return {
    summary: values.summary || String(analysis?.summary || '').trim(),
    text: (values.keyPoints || []).filter((point) => /文字|文本|标题|标识|OCR/iu.test(point)).join('；'),
    keyPoints: values.keyPoints || [],
    tags: values.tags || [],
    entities: values.entities || [],
    analyzedAt: new Date().toISOString(),
    modelId,
    mode,
  };
}

async function analyzeAssistantImageAttachment(attachment, instruction, mode = 'initial', requestToken = null) {
  assertAssistantRequestActive(requestToken);
  const config = modelAnalysisConfiguration('对话图片');
  const descriptor = attachmentDurableDescriptor(attachment);
  let imageDataUrl = '';
  if (isTauriRuntime && descriptor?.assetId && descriptor.state === 'ready') {
    const prepared = await captureImageAnalysisInput({
      ...attachment,
      mimeType: assistantAttachmentMimeType(attachment),
      durableAsset: descriptor,
    });
    imageDataUrl = prepared.dataUrl;
  } else {
    const file = await attachmentBlob(attachment);
    if (!file) return { attachment, available: false };
    imageDataUrl = await imageFileToAnalysisDataUrl(file);
  }
  assertAssistantRequestActive(requestToken);
  const analysis = await invokeContentAnalysis(
    config,
    renderPrompt('assistant.image-analysis-input', {
      INSTRUCTION: instruction,
      IMAGE_NAME: attachment.name,
    }),
    [],
    [imageDataUrl],
    mode === 'initial' ? `图片记忆：${attachment.name}` : `图片进一步分析：${attachment.name}`,
    false,
  );
  assertAssistantRequestActive(requestToken);
  attachment.imageAnalysis = assistantImageAnalysisRecord(analysis, config.modelProfile.selectedModel, mode);
  return { attachment, available: true };
}

function conversationImageAttachments(conversation, excludedIds = new Set()) {
  return (conversation?.messages || []).flatMap((message) => (message.attachments || [])
    .filter((attachment) => isImageAttachment(attachment) && !excludedIds.has(attachment.id))
    .map((attachment) => ({ attachment, message })));
}

function imageReferenceNumber(value) {
  if (/^\d+$/u.test(value)) return Number(value);
  const digits = { 一: 1, 二: 2, 两: 2, 三: 3, 四: 4, 五: 5, 六: 6, 七: 7, 八: 8, 九: 9, 十: 10 };
  return digits[value] || 0;
}

function resolveHistoricalImageReferences(conversation, message, currentAttachments = []) {
  const source = String(message || '').trim();
  const currentIds = new Set(currentAttachments.map((attachment) => attachment.id));
  const history = conversationImageAttachments(conversation, currentIds);
  if (!history.length) return [];
  const selected = new Map();
  const selectAt = (number) => {
    const item = history[number - 1];
    if (item) selected.set(item.attachment.id, item.attachment);
  };
  for (const match of source.matchAll(/第\s*([0-9一二两三四五六七八九十]+)\s*张(?:图片|图)/gu)) selectAt(imageReferenceNumber(match[1]));
  for (const match of source.matchAll(/(?:图片|图)\s*([0-9]+)/gu)) selectAt(Number(match[1]));
  history.forEach(({ attachment }) => {
    const name = String(attachment.name || '').toLocaleLowerCase('zh-CN');
    const stem = name.replace(/\.[^.]+$/u, '');
    const normalizedSource = source.toLocaleLowerCase('zh-CN');
    if ((name.length >= 3 && normalizedSource.includes(name)) || (stem.length >= 3 && normalizedSource.includes(stem))) {
      selected.set(attachment.id, attachment);
    }
  });
  if (/(?:全部|所有|这些|上述|上面这些|刚才这些)(?:的)?\s*(?:图片|图)/u.test(source)) {
    history.forEach(({ attachment }) => selected.set(attachment.id, attachment));
  } else if (/(?:上面|刚才|之前|前面)(?:的)?\s*(?:两|2)\s*张?(?:图片|图)/u.test(source)) {
    history.slice(-2).forEach(({ attachment }) => selected.set(attachment.id, attachment));
  } else if (/(?:上面|刚才|之前|前面)(?:的)?\s*(?:三|3)\s*张?(?:图片|图)/u.test(source)) {
    history.slice(-3).forEach(({ attachment }) => selected.set(attachment.id, attachment));
  } else if (/(?:这张|那张|上面|刚才|之前|前面)(?:的)?\s*(?:图片|图)/u.test(source)) {
    const last = history.at(-1)?.attachment;
    if (last) selected.set(last.id, last);
  }
  return [...selected.values()];
}

function assistantAttachmentMimeType(attachment) {
  const descriptor = attachmentDurableDescriptor(attachment);
  return String(attachment?.type || attachment?.mimeType || descriptor?.mimeType || 'application/octet-stream');
}

function assistantAttachmentVolatileBlob(attachment) {
  return secretaryAttachmentFiles.get(attachment?.id)
    || secretaryAttachmentFiles.get(attachment?.attachmentId)
    || null;
}

function assistantAttachmentAnalysisContext(analysis, attachmentNames, batchMeta = {}) {
  const values = captureAnalysisValues(analysis || {});
  const sourceNames = [...new Set((attachmentNames || []).map((name) => String(name || '').trim()).filter(Boolean))];
  return renderPrompt('assistant.text-attachment-analysis-record', {
    COLLECTION_SUFFIX: sourceNames.length > 1 ? promptText('assistant.collection-suffix') : '',
    ATTACHMENT_NAMES: sourceNames.join('、') || promptText('shared.unnamed-attachment'),
    COMPLETED_CHUNKS: Number(batchMeta.completedChunkCount || 0).toLocaleString('zh-CN'),
    TOTAL_CHUNKS: Number(batchMeta.chunkCount || 0).toLocaleString('zh-CN'),
    ANALYSIS_MARKDOWN: values.analysisMarkdown || values.summary || modelAnalysisSummary(analysis),
    KEY_POINTS: values.keyPoints?.length ? renderPrompt('assistant.text-attachment-key-points', { KEY_POINTS: values.keyPoints.join('\n- ') }) : '',
    TAGS: values.tags?.length ? renderPrompt('assistant.text-attachment-tags', { TAGS: values.tags.join('、') }) : '',
    ENTITIES: values.entities?.length ? renderPrompt('assistant.text-attachment-entities', { ENTITIES: values.entities.join('、') }) : '',
  });
}

function updateAssistantAttachmentProgress(requestToken, attachment, progress = {}) {
  const conversation = workspaceState.conversations.find((item) => item.id === requestToken?.conversationId);
  if (!conversation) return;
  conversation.processingStage = {
    requestId: requestToken.id,
    title: '正在分块分析附件',
    detail: `“${attachment.name || '未命名附件'}”已读取 ${Number(progress.loaded || 0).toLocaleString('zh-CN')}/${Number(progress.total || 0).toLocaleString('zh-CN')} 字节（${Number(progress.percent || 0)}%），每批完成后立即归并。`,
    startedAt: conversation.processingStage?.startedAt || new Date().toISOString(),
    cancellable: true,
  };
  if (workspaceState.activeConversationId === conversation.id) renderSecretaryConversation();
}

async function analyzeAssistantTextAttachment(attachment, config, requestToken = null) {
  const descriptor = attachmentDurableDescriptor(attachment);
  const volatile = assistantAttachmentVolatileBlob(attachment);
  const attachmentName = String(attachment.name || descriptor?.fileName || '').trim()
    || promptText('shared.unnamed-attachment');
  const byteLength = Number(descriptor?.byteLength || volatile?.size || attachment?.size || 0);
  const chunkSize = 1024 * 1024;
  const chunkCount = streamedChunkCount(byteLength, chunkSize);
  const analyses = [];
  const stream = descriptor?.assetId && descriptor.state === 'ready' && isTauriRuntime
    ? streamDurableAssetText(invokeNative, descriptor, {
      chunkSize,
      onProgress: (progress) => updateAssistantAttachmentProgress(requestToken, attachment, progress),
    })
    : volatile instanceof Blob
      ? streamBlobText(volatile, {
        chunkSize,
        onProgress: (progress) => updateAssistantAttachmentProgress(requestToken, attachment, progress),
      })
      : null;
  if (!stream) throw new Error(`附件“${attachment.name || attachment.id || attachmentName}”没有可读取的耐久正文`);
  let batchIndex = 0;
  for await (const text of stream) {
    assertAssistantRequestActive(requestToken);
    batchIndex += 1;
    if (!String(text || '').trim()) continue;
    const analysis = await invokeContentAnalysis(config, renderPrompt('assistant.text-attachment-analysis-batch', {
      ATTACHMENT_NAME: attachmentName,
      BATCH_NUMBER: batchIndex,
      BATCH_COUNT: Math.max(batchIndex, chunkCount),
      BATCH_CONTENT: text,
    }), [], [], `AI助手附件“${attachmentName}”第 ${batchIndex} 批`, false);
    analysis.yunspireAttachmentSource = {
      name: attachmentName,
      mimeType: assistantAttachmentMimeType(attachment),
      batchIndex,
      batchCount: Math.max(batchIndex, chunkCount),
    };
    analyses.push(analysis);
    assertAssistantRequestActive(requestToken);
  }
  if (!analyses.length) return null;
  const consolidated = analyses.length === 1
    ? analyses[0]
    : await consolidateModelAnalyses(config, analyses, `AI助手附件“${attachment.name || '未命名附件'}”`, false);
  consolidated.yunspireBatchMeta = {
    chunkCount: Math.max(chunkCount, batchIndex),
    completedChunkCount: batchIndex,
    consolidationRequired: analyses.length > 1,
    consolidationCompleted: true,
    streamingSourceRead: true,
  };
  return consolidated;
}

async function prepareAssistantAttachmentContext(attachments, historicalReferences = [], unavailableReferences = [], requestToken = null) {
  const modelAttachments = [];
  const textAnalyses = [];
  const textAttachmentNames = [];
  const textAttachments = attachments.filter((attachment) => !isImageAttachment(attachment) && isTextAttachment(attachment));
  const analysisConfig = textAttachments.length ? modelAnalysisConfiguration('AI助手附件') : null;
  for (const attachment of attachments) {
    assertAssistantRequestActive(requestToken);
    const mimeType = assistantAttachmentMimeType(attachment);
    const modelAttachment = { name: attachment.name, mimeType };
    if (isImageAttachment(attachment)) {
      const remembered = imageAnalysisText(attachment);
      if (remembered) modelAttachment.textContent = remembered;
      modelAttachments.push(modelAttachment);
    } else if (isTextAttachment(attachment)) {
      const analysis = await analyzeAssistantTextAttachment(attachment, analysisConfig, requestToken);
      if (analysis) {
        textAnalyses.push(analysis);
        textAttachmentNames.push(attachment.name || '未命名附件');
      }
    } else {
      modelAttachments.push(modelAttachment);
    }
  }
  if (textAnalyses.length) {
    const consolidated = textAnalyses.length === 1
      ? textAnalyses[0]
      : await consolidateModelAnalyses(analysisConfig, textAnalyses, 'AI助手文本附件集合', false);
    const chunkCount = textAnalyses.reduce((total, analysis) => total + Number(analysis.yunspireBatchMeta?.chunkCount || 1), 0);
    const completedChunkCount = textAnalyses.reduce((total, analysis) => total + Number(analysis.yunspireBatchMeta?.completedChunkCount || 1), 0);
    modelAttachments.push({
      name: textAttachmentNames.length === 1 ? textAttachmentNames[0] : `${textAttachmentNames.length} 个文本附件的分层归并`,
      mimeType: 'text/markdown;charset=utf-8',
      textContent: assistantAttachmentAnalysisContext(consolidated, textAttachmentNames, { chunkCount, completedChunkCount }),
    });
  }
  historicalReferences.forEach((attachment) => {
    const remembered = imageAnalysisText(attachment);
    if (remembered) modelAttachments.push({ name: attachment.name, mimeType: attachment.type || 'image/*', textContent: remembered });
  });
  const contextParts = [];
  if (attachments.length) contextParts.push(promptText('assistant.current-attachment-context'));
  if (historicalReferences.length) contextParts.push(renderPrompt('assistant.historical-image-context', {
    IMAGE_NAMES: historicalReferences.map((attachment) => attachment.name).join('、'),
  }));
  if (unavailableReferences.length) contextParts.push(renderPrompt('assistant.unavailable-image-context', {
    IMAGE_NAMES: unavailableReferences.map((attachment) => attachment.name).join('、'),
  }));
  return {
    modelAttachments,
    contextText: contextParts.join('\n'),
  };
}

async function requestAssistantTurn(conversation, modelSelection, attachmentContext = null, requestContext = null) {
  const requestToken = typeof requestContext === 'string'
    ? { id: requestContext, conversationId: conversation?.id, ownerConversationId: conversation?.id, cancelled: false }
    : requestContext;
  assertAssistantRequestActive(requestToken, conversation);
  const { modelProfile, apiKey } = assistantRequestModelConfiguration(requestToken, modelSelection);
  const latestUserMessage = [...(conversation?.messages || [])].reverse().find((message) => message.role === 'user' && message.excludeFromModelContext !== true);
  const slashCommand = latestUserMessage ? parseAssistantCommand(latestUserMessage.content) : null;
  const slashDefinition = assistantSlashCommandDefinition(slashCommand);
  let messages;
  if (requestToken?.nativeRuntime && isTauriRuntime) {
    const context = await invokeNative('assemble_assistant_request_context', {
      input: {
        requestId: requestToken.id,
        conversationRevision: Number(requestToken.conversationRevision || 0),
        messages: conversation.messages || [],
        attachmentContext: attachmentContext || {},
        latestUserOnly: Boolean(slashDefinition),
      },
    });
    requestToken.nativeContextHash = context.contextHash;
    messages = context.messages;
  } else {
    const conversationMessages = assistantConversationMessages(conversation, attachmentContext);
    const lastMessage = conversationMessages.at(-1);
    messages = slashDefinition && lastMessage ? [lastMessage] : conversationMessages;
  }
  const requiredSlashCapability = slashCommand?.name === 'reflect'
    ? 'system:optimization'
    : ['image', 'edit'].includes(slashCommand?.name) ? 'system:image' : '';
  const requestCapabilities = assistantCapabilitiesForRequest(requestToken);
  const capabilities = slashDefinition
    ? requestCapabilities.filter((capability) => capability.id === requiredSlashCapability)
    : requestCapabilities;
  const result = await invokeNative('chat_with_assistant', {
    provider: modelProfile.provider,
    baseUrl: modelProfile.baseUrl,
    apiKey,
    model: modelProfile.selectedModel,
    messages,
    capabilities,
    assistantProfile: workspaceState.assistantProfile || {},
    requestId: requestToken?.id || crypto.randomUUID(),
    traceId: requestToken?.traceId || null,
  });
  if (requestToken?.traceId && result?.traceId && result.traceId !== requestToken.traceId) {
    throw new Error('AI助手模型回执 Trace 与当前请求不一致');
  }
  assertAssistantRequestActive(requestToken, conversation);
  return result;
}

let assistantExecutionChain = Promise.resolve();

async function acquireAssistantExecutionLock() {
  let release;
  const previous = assistantExecutionChain;
  assistantExecutionChain = new Promise((resolve) => { release = resolve; });
  await previous.catch(() => null);
  return release;
}

async function requestStandaloneAssistantDecision(message, label = '后台任务意图分析', scheduleDispatchContext = null) {
  const { modelProfile, apiKey } = modelRoleConfiguration('chat', label);
  const traceId = `trace-${crypto.randomUUID()}`;
  const result = await invokeNative('chat_with_assistant', {
    provider: modelProfile.provider,
    baseUrl: modelProfile.baseUrl,
    apiKey,
    model: modelProfile.selectedModel,
    messages: [{ role: 'user', content: message, attachments: [] }],
    capabilities: assistantCapabilitiesForRequest(null),
    assistantProfile: workspaceState.assistantProfile || {},
    requestId: crypto.randomUUID(),
    traceId,
    scheduleDispatchContext,
  });
  if (result?.traceId && result.traceId !== traceId) throw new Error('后台模型回执 Trace 与当前请求不一致');
  return result;
}

const localKnowledgeCountPattern = /(?:(?:Obsidian|Vault|知识库|资料库|仓库).{0,40}(?:多少|几篇|数量|总数|统计)|(?:多少|几篇|数量|总数).{0,40}(?:笔记|文档|Markdown|仓库|知识库|Vault))/iu;
const assistantContinuationPattern = /^(?:可以|可以的|好的?|好啊|行|没问题|确认|确认执行|继续|继续执行|告诉我(?:结果|答案)?|请告诉我(?:结果|答案)?|结果呢|开始吧|执行吧|那就这样)[。！!？?，,\s]*$/iu;
function isImageAttachment(attachment) {
  return attachment?.kind === 'screenshot' || String(attachment?.type || '').startsWith('image/');
}

function resolveAssistantExecutionMessage(conversation, message) {
  const normalized = String(message || '').replace(/\s+/g, ' ').trim();
  const history = conversation?.messages || [];
  const currentUserIndex = history.findLastIndex((item) => item.role === 'user' && String(item.content || '').trim() === String(message || '').trim());
  const previousAssistantIndex = currentUserIndex > 0
    ? history.slice(0, currentUserIndex).findLastIndex((item) => item.role === 'assistant')
    : -1;
  const previousAssistant = previousAssistantIndex >= 0 ? history[previousAssistantIndex] : null;
  if (previousAssistant?.action === 'clarify') {
    const originalUser = history.slice(0, previousAssistantIndex).findLast((item) => item.role === 'user' && String(item.content || '').trim());
    if (originalUser) return `${originalUser.content.trim()}\n补充信息：${String(message || '').trim()}`;
  }
  if (!assistantContinuationPattern.test(normalized)) return message;
  const previousUserMessage = [...history]
    .slice(0, -1)
    .reverse()
    .find((item) => item.role === 'user' && typeof item.content === 'string' && item.content.trim());
  return previousUserMessage?.content?.trim() && localKnowledgeCountPattern.test(previousUserMessage.content)
    ? previousUserMessage.content.trim()
    : message;
}

function assistantTurnRequestsExecution(turn, message, attachments = [], requestContext = null) {
  void message;
  void attachments;
  const requiredCapability = `system:${turn?.intent || ''}`;
  const allowedCapabilities = new Set(
    assistantCapabilitiesForRequest(requestContext)
      .filter((capability) => capability.enabled)
      .map((capability) => capability.id),
  );
  return turn?.action === 'execute'
    && turn.intent !== 'chat'
    && Number(turn.confidence || 0) >= 0.55
    && Boolean(turn.decisionReceipt)
    && Array.isArray(turn.capabilityIds)
    && turn.capabilityIds.includes(requiredCapability)
    && allowedCapabilities.has(requiredCapability);
}

function validatedAssistantCapabilities(turn, plan, requestContext = null) {
  void plan;
  const allowed = new Map(assistantCapabilitiesForRequest(requestContext).filter((capability) => capability.enabled).map((capability) => [capability.id, capability]));
  const selectedSkillIds = [...selectedCapabilityIdSet(requestContext)].filter((id) => id.startsWith('skill:'));
  const capabilityIds = [...new Set([...(turn.capabilityIds || []), ...selectedSkillIds])];
  return capabilityIds.map((id) => allowed.get(id)).filter(Boolean).slice(0, 16);
}

async function consumeModelDecision(turn, plan, requestContext = null) {
  const capabilityId = `system:${plan.intent}`;
  if (!assistantTurnRequestsExecution(turn, '', [], requestContext)) throw new Error('模型没有授权执行当前系统操作');
  if (!turn.capabilityIds.includes(capabilityId)) throw new Error(`模型没有选择 ${capabilityId} 能力`);
  return {
    executionId: `model-execution-${crypto.randomUUID()}`,
    receipt: turn.decisionReceipt,
    intent: plan.intent,
    operation: turn.operation || 'run',
    parameters: turn.parameters && typeof turn.parameters === 'object' ? turn.parameters : {},
    reason: turn.reason || '',
    confidence: Number(turn.confidence || 0),
    capabilityId,
    analyzedAt: new Date().toISOString(),
  };
}

function commandNetworkTargets(parameters) {
  const values = [
    ...(Array.isArray(parameters?.source_urls) ? parameters.source_urls : []),
    ...(Array.isArray(parameters?.sourceUrls) ? parameters.sourceUrls : []),
  ];
  return uniqueHttpUrls(values);
}

function uniqueHttpUrls(values) {
  const seen = new Set();
  return (Array.isArray(values) ? values : []).flatMap((value) => {
    const target = String(value || '').trim();
    if (!/^https?:\/\//iu.test(target) || seen.has(target)) return [];
    seen.add(target);
    return [target];
  });
}

function explicitEmbeddedLinkCaptureRequest(message) {
  const value = String(message || '').replace(/\s+/gu, ' ').trim();
  return /(?:采集|抓取|访问|继续处理).{0,28}(?:文件|文档|表格|幻灯片|Word|Excel|PPT|刚才|最近|解析).{0,20}(?:链接|网址)|(?:文件|文档|表格|幻灯片|Word|Excel|PPT|刚才|最近|解析).{0,20}(?:链接|网址).{0,28}(?:采集|抓取|访问|继续处理)/iu.test(value);
}

function hydrateEmbeddedLinkCaptureParameters(turn, message) {
  if (turn?.intent !== 'capture' || turn?.parameters?.capture_embedded_links !== true) return [];
  if (!explicitEmbeddedLinkCaptureRequest(message)) {
    throw new Error('模型请求采集文件内链接，但用户消息没有明确提出该操作，已阻止网络访问');
  }
  const available = Array.isArray(workspaceState.lastCaptureRequest?.embeddedLinks)
    ? workspaceState.lastCaptureRequest.embeddedLinks.filter((link) => /^https?:\/\//iu.test(String(link?.target || '')))
    : [];
  if (!available.length) throw new Error('最近一次文件解析没有可采集的 http 或 https 链接');
  const requestedIds = new Set([
    ...(Array.isArray(turn.parameters.embedded_link_ids) ? turn.parameters.embedded_link_ids : []),
    ...(Array.isArray(turn.parameters.embeddedLinkIds) ? turn.parameters.embeddedLinkIds : []),
  ].map((value) => String(value || '').trim()).filter(Boolean));
  const selected = requestedIds.size
    ? available.filter((link) => requestedIds.has(String(link.linkId || link.link_id || '')) || requestedIds.has(String(link.sourceLinkId || link.source_link_id || '')))
    : available;
  if (!selected.length) throw new Error('指定的文件内链接不在最近一次解析结果中');
  const targets = uniqueHttpUrls(selected.map((link) => link.target));
  const embeddedLinkOccurrences = selected.map((link) => ({
    link_id: link.linkId,
    source_link_id: link.sourceLinkId,
    occurrence_index: link.occurrenceIndex,
    target: link.target,
    display_text: link.displayText,
    source: link.source,
    provenance: link.provenance,
    policy: {
      content_role: 'untrusted_data',
      auto_open: false,
      auto_fetch: false,
      capture_requires_explicit_user_request: true,
    },
  }));
  turn.parameters = { ...turn.parameters, source_urls: targets, embedded_link_occurrences: embeddedLinkOccurrences };
  return targets;
}

function commandRelativePaths(parameters) {
  return [...new Set([
    parameters?.target_path,
    parameters?.targetPath,
    parameters?.relative_path,
    parameters?.relativePath,
    parameters?.source_path,
    parameters?.sourcePath,
    parameters?.source_relative_path,
    parameters?.sourceRelativePath,
    parameters?.graph_patch || parameters?.graphPatch ? '.obsidian/graph.json' : '',
  ].map((value) => String(value || '').trim().replace(/^\/+|\\/gu, '/')).filter(Boolean))];
}

const runtimeReadOnlyOperations = new Set(['read', 'query', 'search', 'list', 'open', 'preview']);

function runtimePlanOperation(intent, operation) {
  const normalizedOperation = String(operation || '').trim().toLowerCase();
  if (runtimeReadOnlyOperations.has(normalizedOperation)) return normalizedOperation;
  if (intent === 'search') return 'search';
  if (['dashboard', 'tasks', 'logs', 'settings'].includes(intent)) return 'query';
  return normalizedOperation || 'run';
}

function buildAssistantRuntimeTaskPlan({ title, intent, capabilityId, operation, capabilityIds = [] }) {
  const runtimeOperation = runtimePlanOperation(intent, operation);
  const readOnly = runtimeReadOnlyOperations.has(runtimeOperation);
  return normalizeRuntimeTaskPlanInput({
    schemaVersion: '1.0',
    goal: String(title || intent || 'Assistant capability execution').trim().slice(0, 4_000),
    steps: [
      {
        id: 'capability-main',
        kind: 'capability',
        title: String(intent || 'assistant').trim().slice(0, 240) || 'Assistant capability execution',
        dependsOn: [],
        parameters: {
          capabilityId,
          operation: runtimeOperation,
          effectClass: readOnly ? 'read_only' : 'effectful',
          readOnly,
        },
      },
      {
        id: 'verify-result',
        kind: 'verification',
        title: 'Verify capability result',
        dependsOn: ['capability-main'],
        parameters: { verifier: 'yunspire.runtime.result' },
      },
    ],
    completionContract: {
      mode: 'all_of',
      requirements: [
        {
          id: 'capability-receipt',
          stepId: 'capability-main',
          evidenceType: 'runtime.step_receipt',
          minimumCount: 1,
          description: 'The primary capability must produce a trusted terminal receipt.',
        },
        {
          id: 'verification-receipt',
          stepId: 'verify-result',
          evidenceType: 'runtime.step_receipt',
          minimumCount: 1,
          description: 'The capability result must pass a persisted verification step.',
        },
      ],
    },
    metadata: {
      source: 'assistant.command',
      intent: String(intent || '').trim(),
      capabilityIds: [...new Set((Array.isArray(capabilityIds) ? capabilityIds : [])
        .map((value) => String(value || '').trim())
        .filter(Boolean))].slice(0, 16),
    },
  });
}

async function submitModelAuthorizedCommand(turn, plan, {
  title,
  vaultId = 'all',
  writeTargets = [],
  idempotencyKey = '',
  traceId = '',
} = {}) {
  if (!isTauriRuntime) throw new Error('类型化应用命令只能在 Yunspire 桌面应用中提交');
  const capabilityId = `system:${plan.intent}`;
  const parameters = turn.parameters && typeof turn.parameters === 'object' ? turn.parameters : {};
  const requestedOperation = plan.intent === 'delete' ? 'delete' : turn.operation || 'run';
  const operation = runtimePlanOperation(plan.intent, requestedOperation);
  const runtimePlan = buildAssistantRuntimeTaskPlan({
    title,
    intent: plan.intent,
    capabilityId,
    operation,
    capabilityIds: [
      capabilityId,
      ...(Array.isArray(plan.userSkillSnapshots)
        ? plan.userSkillSnapshots.map((skill) => `skill:${String(skill?.id || '').replace(/^skill:/u, '')}`)
        : []),
    ],
  });
  const permanentDelete = plan.intent === 'delete' && (parameters.permanent_delete === true || parameters.permanentDelete === true);
  const emptyTrash = permanentDelete && (parameters.empty_trash === true || parameters.emptyTrash === true);
  const crossVaultMaintenance = plan.intent === 'knowledge_maintenance' && vaultId === 'all';
  let concreteVaultId = crossVaultMaintenance
    ? 'all'
    : vaultId && vaultId !== 'all'
    ? vaultId
    : plan.intent === 'delete' ? null : writeTargets.find((target) => target?.id && target.id !== 'all')?.id || null;
  if (permanentDelete && emptyTrash) concreteVaultId = 'all';
  if (permanentDelete && !emptyTrash) {
    const operationId = String(parameters.trash_operation_id || parameters.trashOperationId || '').trim();
    if (operationId) {
      const entries = await invokeNative('list_yunspire_trash_entries');
      const entry = entries.find((item) => item.operationId === operationId);
      if (entry) concreteVaultId = entry.vaultId;
    }
  }
  if (plan.intent === 'vaults' && operation === 'restore') {
    const operationId = String(parameters.trash_operation_id || parameters.trashOperationId || '').trim();
    const explicitTargetVaultId = String(parameters.target_vault_id || parameters.targetVaultId || '').trim();
    if (operationId) {
      const entries = await invokeNative('list_yunspire_trash_entries');
      const entry = entries.find((item) => item.operationId === operationId);
      if (entry) {
        concreteVaultId = entry.entryType === 'vault'
          ? entry.vaultId
          : explicitTargetVaultId || concreteVaultId || entry.vaultId;
      } else if (explicitTargetVaultId) {
        concreteVaultId = explicitTargetVaultId;
      }
    } else if (explicitTargetVaultId) {
      concreteVaultId = explicitTargetVaultId;
    }
  }
  const declaredVaultIds = [...new Set([
    concreteVaultId,
    ...writeTargets.map((target) => target?.id),
  ].map((value) => String(value || '').trim()).filter((value) => value && value !== 'all'))];
  const commandId = `command-${crypto.randomUUID()}`;
  const command = {
    id: commandId,
    commandType: 'assistant.operation',
    origin: 'assistant',
    intent: plan.intent,
    capabilityId,
    operation,
    parameters,
    vaultId: concreteVaultId,
    relativePaths: commandRelativePaths(parameters),
    networkTargets: commandNetworkTargets(parameters),
    declaredScope: [
      `capability:${capabilityId}`,
      ...(declaredVaultIds.length
        ? declaredVaultIds.map((targetVaultId) => `vault:${targetVaultId}`)
        : ['runtime:local']),
    ],
    budget: {
      maxSteps: Math.max(16, Math.min(512, Number(plan.steps?.length || 0) * 4 + 4)),
      maxRuntimeSeconds: 3600,
      maxToolCalls: 256,
      maxTokens: 1_000_000,
      maxCost: null,
    },
    idempotencyKey: idempotencyKey || `assistant-${crypto.randomUUID()}`,
    traceId: traceId || turn.traceId || `trace-${crypto.randomUUID()}`,
    modelDecisionReceipt: turn.decisionReceipt,
    runtimePlan,
  };
  const receipt = await invokeNative('submit_application_command', { command });
  if (receipt?.decision?.outcome === 'deny' || !receipt?.taskId || !receipt?.executionTicket?.token) {
    throw new Error(`本地策略拒绝执行：${(receipt?.decision?.reasonCodes || ['unknown']).join('、')}`);
  }
  return {
    ...receipt,
    runtimePlan,
    runtimeCommandTemplate: {
      commandType: 'runtime.step',
      intent: command.intent,
      capabilityId: command.capabilityId,
      operation: command.operation,
      parameters: command.parameters,
      vaultId: command.vaultId,
      relativePaths: command.relativePaths,
      networkTargets: command.networkTargets,
      declaredScope: command.declaredScope,
      budget: command.budget,
    },
  };
}

async function createDirectVaultWriteTask({ title, vaultId, vaultIds = [], relativePaths, operation = 'create' }) {
  if (!isTauriRuntime) throw new Error('Obsidian 写入只能在 Yunspire 桌面应用中执行');
  const paths = [...new Set((relativePaths || []).map((path) => String(path || '').trim()).filter(Boolean))];
  const declaredVaultIds = [...new Set([vaultId, ...vaultIds]
    .map((value) => String(value || '').trim())
    .filter((value) => value && value !== 'all'))];
  if (!declaredVaultIds.length) throw new Error('Obsidian 写入缺少明确的 Vault 范围');
  const receipt = await invokeNative('submit_application_command', {
    command: {
      id: `command-${crypto.randomUUID()}`,
      commandType: 'direct.vault.write',
      origin: 'direct_user',
      intent: 'vaults',
      capabilityId: 'system:vaults',
      operation,
      parameters: { title: String(title || 'Obsidian 写入').slice(0, 240), target_paths: paths },
      vaultId,
      relativePaths: paths,
      networkTargets: [],
      declaredScope: ['capability:system:vaults', ...declaredVaultIds.map((targetVaultId) => `vault:${targetVaultId}`)],
      budget: {
        maxSteps: Math.max(1, Math.min(512, paths.length + 2)),
        maxRuntimeSeconds: 900,
        maxToolCalls: Math.max(1, Math.min(2048, paths.length + 2)),
        maxTokens: null,
        maxCost: null,
      },
      idempotencyKey: `direct-write-${crypto.randomUUID()}`,
      traceId: `trace-${crypto.randomUUID()}`,
      modelDecisionReceipt: null,
    },
  });
  if (receipt?.decision?.outcome === 'deny' || !receipt?.taskId || !receipt?.executionTicket?.token) {
    throw new Error(`本地策略拒绝写入：${(receipt?.decision?.reasonCodes || ['missing_execution_ticket']).join('、')}`);
  }
  const task = applyNativeCommandReceipt({
    title: String(title || 'Obsidian 写入'),
    intent: 'vaults',
    operation,
    vaultId,
    writeTargetVaultIds: declaredVaultIds,
    state: 'queued',
    progress: 0,
    autoManagedWrite: true,
  }, receipt);
  await transitionNativeTask(task, 'start', '用户直接写入已进入能力范围执行器', 5, {
    id: `direct-write-${crypto.randomUUID()}`,
    phase: 'write-preparation',
    relativePaths: paths,
  });
  return task;
}

async function createOptimizationRuntimeTask({
  title,
  operation,
  candidateId = null,
  targetVersion = null,
  action = '',
  origin = 'direct_user',
  autoExecute = false,
}) {
  if (!isTauriRuntime || !localWorkspaceReady) throw new Error('优化配置变更只能在已授权的 Yunspire 桌面工作区执行');
  const capabilityId = 'system:optimization';
  if (operation !== 'run') throw new Error('优化 Runtime 只允许 system:optimization/run');
  const commandOrigin = origin === 'evolution' ? 'evolution' : 'direct_user';
  const mutationAction = action || (candidateId ? 'apply' : 'rollback');
  const runtimePlan = buildAssistantRuntimeTaskPlan({
    title,
    intent: 'optimization',
    capabilityId,
    operation,
    capabilityIds: [capabilityId],
  });
  const parameters = {
    action: mutationAction,
    ...(candidateId ? { candidate_id: candidateId } : {}),
    ...(targetVersion !== null ? { target_version: targetVersion } : {}),
  };
  const budget = {
    maxSteps: 8,
    maxRuntimeSeconds: 300,
    maxToolCalls: 16,
    maxTokens: null,
    maxCost: null,
  };
  const command = {
    id: `command-${crypto.randomUUID()}`,
    commandType: 'direct.optimization',
    origin: commandOrigin,
    intent: 'optimization',
    capabilityId,
    operation,
    parameters,
    vaultId: null,
    relativePaths: [],
    networkTargets: [],
    declaredScope: ['capability:system:optimization'],
    budget,
    idempotencyKey: `${commandOrigin}-optimization-${mutationAction}-${crypto.randomUUID()}`,
    traceId: `trace-${crypto.randomUUID()}`,
    modelDecisionReceipt: null,
    runtimePlan,
  };
  const receipt = await invokeNative('submit_application_command', { command });
  if (receipt?.decision?.outcome !== 'allow' || !receipt?.taskId || !receipt?.executionTicket?.token) {
    throw new Error(`本地策略拒绝优化配置变更：${(receipt?.decision?.reasonCodes || ['missing_execution_ticket']).join('、')}`);
  }
  const task = applyNativeCommandReceipt({
    title,
    intent: 'optimization',
    modelOperation: operation,
    state: 'queued',
    progress: 0,
    directUserOperation: commandOrigin === 'direct_user',
    autoExecute: autoExecute === true,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  }, {
    ...receipt,
    runtimePlan,
    runtimeCommandTemplate: {
      commandType: 'runtime.step',
      intent: command.intent,
      capabilityId,
      operation,
      parameters,
      vaultId: null,
      relativePaths: [],
      networkTargets: [],
      declaredScope: command.declaredScope,
      budget,
    },
  });
  syncSecretaryTask(task);
  return task;
}

async function executeOptimizationRuntimeMutation(task, mutation) {
  let capabilityClaim = null;
  let capabilityStepSettled = false;
  try {
    await transitionNativeTask(
      task,
      'start',
      task.directUserOperation ? '用户确认的优化配置变更已进入原生执行器' : '后台优化任务已进入原生执行器',
      5,
    );
    const step = await claimAssistantRuntimeStep(task, 'capability-main');
    if (step.receipt) throw new Error('优化配置任务意外复用了已结算步骤');
    capabilityClaim = step.claim;
    await submitAssistantRuntimeChild(task, capabilityClaim);
    const result = await mutation(nativeOperationContext(task));
    await settleAssistantRuntimeChild(task, 'succeeded', '优化配置变更已由原生处理器完成');
    await settleAssistantRuntimeStep(task, capabilityClaim, {
      stepId: 'capability-main',
      state: 'succeeded',
      reply: '优化配置变更已由原生处理器完成',
    });
    capabilityStepSettled = true;
    await settleNativeTask(task, 'succeeded', '优化配置变更已完成并写入可信回执');
    updateTaskExecution(task, 'succeeded', '优化配置变更已完成并写入可信回执', 100);
    syncSecretaryTask(task);
    return result;
  } catch (error) {
    await settleAssistantRuntimeChild(task, 'failed', String(error)).catch(() => null);
    if (capabilityClaim && !capabilityStepSettled) {
      await settleAssistantRuntimeStep(task, capabilityClaim, {
        stepId: 'capability-main',
        state: 'failed',
        reply: String(error),
      }).catch(() => null);
    }
    await settleNativeTask(task, 'failed', String(error)).catch(() => null);
    updateTaskExecution(task, 'failed', String(error), 0);
    syncSecretaryTask(task);
    throw error;
  }
}

